def split_unmapped_regions(rows, county_to_region):
    accepted, quarantine = [], []
    for row in rows:
        region = county_to_region.get(row['county'])
        if region is None:
            quarantine.append(row)
        else:
            accepted.append({**row, 'region': region})
    return accepted, quarantine

