from .regions import split_unmapped_regions
from .amounts import convert_amounts
def prepare_daily(rows, county_to_region):
    mapped, rejected = split_unmapped_regions(rows, county_to_region)
    return {'sales': convert_amounts(mapped), 'quarantine': rejected}
